import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ScrollingModule } from '@angular/cdk/scrolling';
import { MatToolbarModule } from '@angular/material/toolbar';
import { MatIconModule } from '@angular/material/icon';
import { MatButtonModule } from '@angular/material/button';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatMenuModule } from '@angular/material/menu';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatTooltipModule } from '@angular/material/tooltip';
import { Subject, debounceTime, distinctUntilChanged, takeUntil } from 'rxjs';
import { MailListItemComponent } from '../mail-list-item/mail-list-item.component';
import { MailMessage } from '../../models/mail.model';


@Component({
  selector: 'app-mail-list',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    ScrollingModule,
    MatToolbarModule,
    MatIconModule,
    MatButtonModule,
    MatCheckboxModule,
    MatMenuModule,
    MatFormFieldModule,
    MatInputModule,
    MatTooltipModule,
    MailListItemComponent,
  ],
  templateUrl: './mail-list.component.html',
  styleUrls: ['./mail-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MailListComponent implements OnInit, OnDestroy {
  @Input() messages: MailMessage[] = [];
  @Input() selectedMessageId: string | null = null;
  @Input() folderName: string = '受信トレイ';
  @Input() layoutMode: 'split' | 'list' = 'list';

  @Output() messageSelected = new EventEmitter<string>();
  @Output() messagesChecked = new EventEmitter<string[]>();
  @Output() starToggled = new EventEmitter<string>();
  @Output() deleteRequested = new EventEmitter<string[]>();
  @Output() moveRequested = new EventEmitter<{ ids: string[]; folderId: string }>();
  @Output() readToggled = new EventEmitter<string[]>();
  @Output() searchChanged = new EventEmitter<string>();
  @Output() layoutModeChanged = new EventEmitter<'split' | 'list'>();

  checkedIds = new Set<string>();
  searchTerm = '';
  allChecked = false;

  // Pagination
  pageSize = 50;
  currentPage = 0;

  private searchSubject = new Subject<string>();
  private destroy$ = new Subject<void>();

  ngOnInit(): void {
    this.searchSubject.pipe(
      debounceTime(300),
      distinctUntilChanged(),
      takeUntil(this.destroy$),
    ).subscribe(term => {
      this.searchChanged.emit(term);
    });
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  onSearchInput(event: Event): void {
    const value = (event.target as HTMLInputElement).value;
    this.searchSubject.next(value);
  }

  onClearSearch(): void {
    this.searchTerm = '';
    this.searchSubject.next('');
  }

  onMessageClick(id: string): void {
    this.messageSelected.emit(id);
  }

  onCheckChanged(event: { id: string; checked: boolean }): void {
    if (event.checked) {
      this.checkedIds.add(event.id);
    } else {
      this.checkedIds.delete(event.id);
    }
    this.allChecked = this.checkedIds.size === this.messages.length && this.messages.length > 0;
    this.messagesChecked.emit(Array.from(this.checkedIds));
  }

  onSelectAll(checked: boolean): void {
    if (checked) {
      this.messages.forEach(m => this.checkedIds.add(m.id));
    } else {
      this.checkedIds.clear();
    }
    this.allChecked = checked;
    this.messagesChecked.emit(Array.from(this.checkedIds));
  }

  onStarToggle(id: string): void {
    this.starToggled.emit(id);
  }

  onDeleteChecked(): void {
    this.deleteRequested.emit(Array.from(this.checkedIds));
    this.checkedIds.clear();
    this.allChecked = false;
  }

  onDeleteSingle(id: string): void {
    this.deleteRequested.emit([id]);
    this.checkedIds.delete(id);
  }

  onMarkReadChecked(): void {
    this.readToggled.emit(Array.from(this.checkedIds));
  }

  onReadToggleSingle(id: string): void {
    this.readToggled.emit([id]);
  }

  onMoveChecked(folderId: string): void {
    this.moveRequested.emit({ ids: Array.from(this.checkedIds), folderId });
    this.checkedIds.clear();
    this.allChecked = false;
  }

  isChecked(id: string): boolean {
    return this.checkedIds.has(id);
  }

  get hasChecked(): boolean {
    return this.checkedIds.size > 0;
  }

  // Pagination
  get totalPages(): number {
    return Math.ceil(this.messages.length / this.pageSize);
  }

  get pagedMessages(): MailMessage[] {
    const start = this.currentPage * this.pageSize;
    return this.messages.slice(start, start + this.pageSize);
  }

  get pageStart(): number {
    return this.currentPage * this.pageSize + 1;
  }

  get pageEnd(): number {
    return Math.min((this.currentPage + 1) * this.pageSize, this.messages.length);
  }

  get hasPrevPage(): boolean {
    return this.currentPage > 0;
  }

  get hasNextPage(): boolean {
    return this.currentPage < this.totalPages - 1;
  }

  onPrevPage(): void {
    if (this.hasPrevPage) {
      this.currentPage--;
    }
  }

  onNextPage(): void {
    if (this.hasNextPage) {
      this.currentPage++;
    }
  }

  onRefresh(): void {
    // Trigger a search with current term to reload
    this.searchChanged.emit(this.searchTerm);
  }

  onSetLayoutMode(mode: 'split' | 'list'): void {
    this.layoutModeChanged.emit(mode);
  }

  trackByMessageId(_index: number, message: MailMessage): string {
    return message.id;
  }
}
