import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatListModule } from '@angular/material/list';
import { MatIconModule } from '@angular/material/icon';
import { MatButtonModule } from '@angular/material/button';
import { MatBadgeModule } from '@angular/material/badge';
import { MatDividerModule } from '@angular/material/divider';
import { MailFolder } from '../../models/folder.model';

@Component({
  selector: 'app-mail-sidebar',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    MatListModule,
    MatIconModule,
    MatButtonModule,
    MatBadgeModule,
    MatDividerModule,
  ],
  templateUrl: './mail-sidebar.component.html',
  styleUrls: ['./mail-sidebar.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MailSidebarComponent {
  @Input() folders: MailFolder[] = [];
  @Input() selectedFolderId: string = 'inbox';
  @Input() availableColors: string[] = [];

  @Output() folderSelected = new EventEmitter<string>();
  @Output() composeClicked = new EventEmitter<void>();
  @Output() labelCreated = new EventEmitter<{ name: string; color: string }>();

  showCreateForm = false;
  newLabelName = '';
  selectedColor = '#e53935';

  get systemFolders(): MailFolder[] {
    return this.folders.filter(f => f.type === 'system');
  }

  get labelFolders(): MailFolder[] {
    return this.folders.filter(f => f.type === 'label');
  }

  onFolderClick(folderId: string): void {
    this.folderSelected.emit(folderId);
  }

  onCompose(): void {
    this.composeClicked.emit();
  }

  onShowCreateForm(): void {
    this.showCreateForm = true;
    this.newLabelName = '';
    this.selectedColor = this.availableColors.length > 0 ? this.availableColors[0] : '#e53935';
  }

  onCancelCreate(): void {
    this.showCreateForm = false;
    this.newLabelName = '';
  }

  onSelectColor(color: string): void {
    this.selectedColor = color;
  }

  onSaveLabel(): void {
    const name = this.newLabelName.trim();
    if (name) {
      this.labelCreated.emit({ name, color: this.selectedColor });
      this.showCreateForm = false;
      this.newLabelName = '';
    }
  }
}
