import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy, OnInit, OnChanges, SimpleChanges, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatIconModule } from '@angular/material/icon';
import { MatButtonModule } from '@angular/material/button';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatChipsModule } from '@angular/material/chips';
import { MatAutocompleteModule } from '@angular/material/autocomplete';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MatDividerModule } from '@angular/material/divider';
import { MailMessage, MailAddress, MailDraft } from '../../models/mail.model';
/* STEP 8 / Phase 2.2: KeyboardManager 適用 */
import { KeyboardManagerService } from '../../../../shared/services/keyboard-manager.service';
import { Subscription } from 'rxjs';
import { OnDestroy } from '@angular/core';

export interface ComposeConfig {
  mode: 'new' | 'reply' | 'replyAll' | 'forward';
  originalMessage?: MailMessage;
  /** 新規作成時の宛先プリフィル (ユーザー指示 2026-04-21) */
  prefillTo?: MailAddress;
  /** 新規作成時の件名プリフィル */
  prefillSubject?: string;
}

@Component({
  selector: 'app-mail-compose',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    MatIconModule,
    MatButtonModule,
    MatFormFieldModule,
    MatInputModule,
    MatChipsModule,
    MatAutocompleteModule,
    MatTooltipModule,
    MatDividerModule,
  ],
  templateUrl: './mail-compose.component.html',
  styleUrls: ['./mail-compose.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MailComposeComponent implements OnInit, OnChanges, OnDestroy {
  /* STEP 8 / Phase 2.2: KeyboardManager で SP キーボード時の compose 高さを制御 */
  keyboardHeight = 0;
  private keyboardSub?: Subscription;
  @Input() config: ComposeConfig = { mode: 'new' };
  @Input() contacts: MailAddress[] = [];
  @Input() isVisible: boolean = false;

  @Output() sendMail = new EventEmitter<MailDraft>();
  @Output() saveDraft = new EventEmitter<MailDraft>();
  @Output() closed = new EventEmitter<void>();

  toRecipients: MailAddress[] = [];
  ccRecipients: MailAddress[] = [];
  bccRecipients: MailAddress[] = [];
  subject = '';
  bodyText = '';
  showCcBcc = false;
  isMinimized = false;
  isMaximized = false;
  toInput = '';
  ccInput = '';
  bccInput = '';
  filteredContacts: MailAddress[] = [];
  isDragOver = false;

  /** 添付ファイル (ユーザー指示 2026-04-21: スマホでも添付可能に) */
  attachments: { name: string; size: number; type: string; file: File }[] = [];

  /** 予約送信モーダル表示フラグ */
  showScheduleModal = false;
  scheduleDate = '';
  scheduleTime = '';

  /** AI 文書生成モーダル表示フラグ */
  showAiModal = false;
  aiPrompt = '';
  aiMode: 'compose' | 'reply' | 'polish' = 'compose';
  aiGenerating = false;

  private myEmail = 'ishizaki.taichi@example.co.jp';

  constructor(
    private cdr: ChangeDetectorRef,
    private keyboard: KeyboardManagerService,
  ) {}

  ngOnInit(): void {
    this.initializeFromConfig();
    /* STEP 8 / Phase 2.2: キーボード高さ購読 → modal の bottom padding を補正 */
    this.keyboardSub = this.keyboard.keyboardHeight$.subscribe(h => {
      this.keyboardHeight = h;
      this.cdr.markForCheck();
    });
  }

  ngOnDestroy(): void {
    this.keyboardSub?.unsubscribe();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['config'] && !changes['config'].firstChange) {
      this.initializeFromConfig();
    }
  }

  private initializeFromConfig(): void {
    const { mode, originalMessage, prefillTo, prefillSubject } = this.config;
    if (!originalMessage) {
      this.reset();
      // 新規作成 + 宛先プリフィル対応 (ユーザー指示 2026-04-21)
      if (mode === 'new') {
        if (prefillTo && prefillTo.email) {
          this.toRecipients = [prefillTo];
        }
        if (prefillSubject) {
          this.subject = prefillSubject;
        }
        this.cdr.markForCheck();
      }
      return;
    }

    switch (mode) {
      case 'reply':
        this.toRecipients = [originalMessage.from];
        this.subject = originalMessage.subject.startsWith('Re: ')
          ? originalMessage.subject
          : `Re: ${originalMessage.subject}`;
        this.bodyText = this.buildQuotedBody(originalMessage);
        break;

      case 'replyAll':
        this.toRecipients = [originalMessage.from];
        const additionalTo = originalMessage.to.filter(a => a.email !== this.myEmail);
        this.toRecipients.push(...additionalTo);
        if (originalMessage.cc) {
          this.ccRecipients = originalMessage.cc.filter(a => a.email !== this.myEmail);
          if (this.ccRecipients.length > 0) this.showCcBcc = true;
        }
        this.subject = originalMessage.subject.startsWith('Re: ')
          ? originalMessage.subject
          : `Re: ${originalMessage.subject}`;
        this.bodyText = this.buildQuotedBody(originalMessage);
        break;

      case 'forward':
        this.toRecipients = [];
        this.subject = originalMessage.subject.startsWith('Fwd: ')
          ? originalMessage.subject
          : `Fwd: ${originalMessage.subject}`;
        this.bodyText = this.buildForwardedBody(originalMessage);
        break;

      default:
        this.reset();
    }
    this.cdr.markForCheck();
  }

  private buildQuotedBody(msg: MailMessage): string {
    const date = new Date(msg.date);
    const dateStr = `${date.getFullYear()}/${date.getMonth() + 1}/${date.getDate()} ${date.getHours()}:${date.getMinutes().toString().padStart(2, '0')}`;
    return `\n\n${dateStr} ${msg.from.name} <${msg.from.email}>:\n> ${msg.body.replace(/\n/g, '\n> ')}`;
  }

  private buildForwardedBody(msg: MailMessage): string {
    const date = new Date(msg.date);
    const dateStr = `${date.getFullYear()}/${date.getMonth() + 1}/${date.getDate()} ${date.getHours()}:${date.getMinutes().toString().padStart(2, '0')}`;
    return `\n\n---------- 転送メッセージ ----------\nFrom: ${msg.from.name} <${msg.from.email}>\n日付: ${dateStr}\n件名: ${msg.subject}\nTo: ${msg.to.map(a => `${a.name} <${a.email}>`).join(', ')}\n\n${msg.body}`;
  }

  private reset(): void {
    this.toRecipients = [];
    this.ccRecipients = [];
    this.bccRecipients = [];
    this.subject = '';
    this.bodyText = '';
    this.showCcBcc = false;
    this.toInput = '';
    this.ccInput = '';
    this.bccInput = '';
  }

  onFilterContacts(value: string, field: 'to' | 'cc' | 'bcc'): void {
    if (!value) {
      this.filteredContacts = [];
      return;
    }
    const term = value.toLowerCase();
    const excludeEmails = new Set([
      ...this.toRecipients.map(r => r.email),
      ...this.ccRecipients.map(r => r.email),
      ...this.bccRecipients.map(r => r.email),
    ]);
    this.filteredContacts = this.contacts.filter(c =>
      !excludeEmails.has(c.email) &&
      (c.name.toLowerCase().includes(term) || c.email.toLowerCase().includes(term))
    );
    this.cdr.markForCheck();
  }

  onAddRecipient(contact: MailAddress, field: 'to' | 'cc' | 'bcc'): void {
    switch (field) {
      case 'to': this.toRecipients = [...this.toRecipients, contact]; this.toInput = ''; break;
      case 'cc': this.ccRecipients = [...this.ccRecipients, contact]; this.ccInput = ''; break;
      case 'bcc': this.bccRecipients = [...this.bccRecipients, contact]; this.bccInput = ''; break;
    }
    this.filteredContacts = [];
    this.cdr.markForCheck();
  }

  onAddRecipientFromInput(field: 'to' | 'cc' | 'bcc'): void {
    let input = '';
    switch (field) {
      case 'to': input = this.toInput; break;
      case 'cc': input = this.ccInput; break;
      case 'bcc': input = this.bccInput; break;
    }
    if (!input.trim()) return;

    const contact = this.contacts.find(c => c.email === input.trim() || c.name === input.trim());
    if (contact) {
      this.onAddRecipient(contact, field);
    } else if (input.includes('@')) {
      this.onAddRecipient({ name: input.trim(), email: input.trim() }, field);
    }
  }

  onRemoveRecipient(email: string, field: 'to' | 'cc' | 'bcc'): void {
    switch (field) {
      case 'to': this.toRecipients = this.toRecipients.filter(r => r.email !== email); break;
      case 'cc': this.ccRecipients = this.ccRecipients.filter(r => r.email !== email); break;
      case 'bcc': this.bccRecipients = this.bccRecipients.filter(r => r.email !== email); break;
    }
    this.cdr.markForCheck();
  }

  onSend(): void {
    if (this.toRecipients.length === 0) return;

    const draft: MailDraft = {
      to: this.toRecipients,
      cc: this.ccRecipients.length > 0 ? this.ccRecipients : undefined,
      bcc: this.bccRecipients.length > 0 ? this.bccRecipients : undefined,
      subject: this.subject,
      body: this.bodyText,
      bodyHtml: `<div style="font-family: sans-serif;">${this.bodyText.replace(/\n/g, '<br>')}</div>`,
      mode: this.config.mode,
      inReplyTo: this.config.originalMessage?.id,
      threadId: this.config.originalMessage?.threadId,
    };
    this.sendMail.emit(draft);
    this.reset();
  }

  onSaveDraft(): void {
    const draft: MailDraft = {
      to: this.toRecipients,
      cc: this.ccRecipients.length > 0 ? this.ccRecipients : undefined,
      bcc: this.bccRecipients.length > 0 ? this.bccRecipients : undefined,
      subject: this.subject,
      body: this.bodyText,
      bodyHtml: `<div style="font-family: sans-serif;">${this.bodyText.replace(/\n/g, '<br>')}</div>`,
      mode: this.config.mode,
    };
    this.saveDraft.emit(draft);
  }

  onClose(): void {
    this.closed.emit();
  }

  onMinimize(): void {
    this.isMinimized = !this.isMinimized;
    if (this.isMinimized) this.isMaximized = false;
  }

  onMaximize(): void {
    this.isMaximized = !this.isMaximized;
    if (this.isMaximized) this.isMinimized = false;
  }

  onDragOver(event: DragEvent): void {
    event.preventDefault();
    this.isDragOver = true;
  }

  onDragLeave(): void {
    this.isDragOver = false;
  }

  onDrop(event: DragEvent): void {
    event.preventDefault();
    this.isDragOver = false;
    const files = event.dataTransfer?.files;
    if (files) this.addFiles(Array.from(files));
  }

  /** 添付ファイル追加 (ユーザー指示 2026-04-21) */
  onAttachClick(): void {
    const input = document.createElement('input');
    input.type = 'file';
    input.multiple = true;
    input.onchange = () => {
      if (input.files) this.addFiles(Array.from(input.files));
    };
    input.click();
  }
  private addFiles(files: File[]): void {
    files.forEach(f => this.attachments.push({ name: f.name, size: f.size, type: f.type, file: f }));
    this.cdr.markForCheck();
  }
  removeAttachment(i: number): void {
    this.attachments.splice(i, 1);
    this.cdr.markForCheck();
  }
  formatFileSize(bytes: number): string {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
  }

  /** 予約送信モーダル開閉 */
  openScheduleSend(): void {
    if (this.toRecipients.length === 0) return;
    // 30 分後を初期値にセット
    const d = new Date(Date.now() + 30 * 60 * 1000);
    this.scheduleDate = d.toISOString().split('T')[0];
    const hh = String(d.getHours()).padStart(2, '0');
    const mm = String(d.getMinutes()).padStart(2, '0');
    this.scheduleTime = `${hh}:${mm}`;
    this.showScheduleModal = true;
    this.cdr.markForCheck();
  }
  cancelScheduleSend(): void { this.showScheduleModal = false; }
  confirmScheduleSend(): void {
    if (!this.scheduleDate || !this.scheduleTime) return;
    const scheduledAt = new Date(`${this.scheduleDate}T${this.scheduleTime}`);
    const draft: MailDraft = {
      to: this.toRecipients,
      cc: this.ccRecipients.length > 0 ? this.ccRecipients : undefined,
      bcc: this.bccRecipients.length > 0 ? this.bccRecipients : undefined,
      subject: this.subject,
      body: this.bodyText,
      bodyHtml: `<div style="font-family: sans-serif;">${this.bodyText.replace(/\n/g, '<br>')}</div>`,
      mode: this.config.mode,
      scheduledAt,
    } as any;
    this.sendMail.emit(draft);
    this.showScheduleModal = false;
    this.reset();
  }

  /** AI 文書作成モーダル開閉 */
  openAiCompose(): void {
    this.aiPrompt = '';
    this.aiMode = this.config.mode === 'reply' || this.config.mode === 'replyAll' ? 'reply' : 'compose';
    this.showAiModal = true;
    this.cdr.markForCheck();
  }
  cancelAiCompose(): void { this.showAiModal = false; }
  generateAiBody(): void {
    if (!this.aiPrompt.trim()) return;
    this.aiGenerating = true;
    this.cdr.markForCheck();
    // モック: 1.5s 後にそれっぽい文面を返す
    setTimeout(() => {
      const recipient = this.toRecipients[0]?.name || 'ご担当者';
      const prompt = this.aiPrompt.trim();
      const body =
        this.aiMode === 'reply'
          ? `${recipient} 様\n\nお世話になっております。石澤です。\n\n${prompt}について承知いたしました。\nご確認いただきありがとうございます。引き続きよろしくお願いいたします。\n\n石澤\n`
          : this.aiMode === 'polish'
          ? this.bodyText.replace(/\s+$/g, '') + '\n\n（AI により表現を調整しました）\n'
          : `${recipient} 様\n\nお世話になっております。石澤です。\n\n${prompt}の件でご連絡いたしました。\nご確認のほどよろしくお願いいたします。\n\n石澤\n`;
      this.bodyText = body;
      this.aiGenerating = false;
      this.showAiModal = false;
      this.cdr.markForCheck();
    }, 1500);
  }

  get modeLabel(): string {
    switch (this.config.mode) {
      case 'reply': return '返信';
      case 'replyAll': return '全員に返信';
      case 'forward': return '転送';
      default: return '新規メッセージ';
    }
  }
}
