import { Component, ChangeDetectionStrategy, ChangeDetectorRef, OnInit, OnDestroy, HostListener } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute } from '@angular/router';
import { Title } from '@angular/platform-browser';
import { MatIconModule } from '@angular/material/icon';
import { MatButtonModule } from '@angular/material/button';
import { MatTooltipModule } from '@angular/material/tooltip';
import { NotificationService } from '../../../../shared/services/notification.service';
import { Subject, takeUntil } from 'rxjs';
import { MailSidebarComponent } from '../../components/mail-sidebar/mail-sidebar.component';
import { MailListComponent } from '../../components/mail-list/mail-list.component';
import { MailReaderComponent } from '../../components/mail-reader/mail-reader.component';
import { MailComposeComponent, ComposeConfig } from '../../components/mail-compose/mail-compose.component';
import { MailService } from '../../services/mail.service';
import { MailMessage, MailAddress, MailDraft } from '../../models/mail.model';
import { MailFolder } from '../../models/folder.model';

type ViewMode = 'three-pane' | 'two-pane' | 'list-reader-toggle' | 'single-pane';

@Component({
  selector: 'app-mail-page',
  standalone: true,
  imports: [
    CommonModule,
    MatIconModule,
    MatButtonModule,
    MatTooltipModule,
    MailSidebarComponent,
    MailListComponent,
    MailReaderComponent,
    MailComposeComponent,
  ],
  templateUrl: './mail-page.component.html',
  styleUrls: ['./mail-page.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MailPageComponent implements OnInit, OnDestroy {
  folders: MailFolder[] = [];
  messages: MailMessage[] = [];
  selectedFolderId = 'inbox';
  selectedMessage: MailMessage | null = null;
  threadMessages: MailMessage[] = [];
  contacts: MailAddress[] = [];

  showCompose = false;
  composeConfig: ComposeConfig = { mode: 'new' };

  viewMode: ViewMode = 'three-pane';
  layoutMode: 'split' | 'list' = 'list'; // User-selectable: split=3-pane, list=list/detail toggle
  showReader = false; // For toggle modes
  showSidebar = true;
  mobileSidebarOpen = false;

  private destroy$ = new Subject<void>();

  constructor(
    private mailService: MailService,
    private cdr: ChangeDetectorRef,
    private titleService: Title,
    private notification: NotificationService,
    private route: ActivatedRoute,
  ) {}

  ngOnInit(): void {
    this.titleService.setTitle('メール | 日程調整ツール"スケコン"');
    this.updateViewMode();
    this.loadFolders();
    this.loadMessages();
    this.loadContacts();

    // クエリパラメータで新規メール作成 (ユーザー指示 2026-04-21):
    // /mail?compose=new&to=foo@x.com&toName=Foo
    this.route.queryParams.pipe(takeUntil(this.destroy$)).subscribe(params => {
      if (params['compose'] === 'new' && params['to']) {
        this.composeConfig = {
          mode: 'new',
          prefillTo: {
            email: params['to'],
            name: params['toName'] || params['to'],
          },
          prefillSubject: params['subject'] || undefined,
        };
        this.showCompose = true;
        this.cdr.markForCheck();
      }
    });
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  @HostListener('window:resize')
  onResize(): void {
    /* fix #19 (R-MAIL-05, 2026-04-27): 三カラム→単カラム切替時に
       表示中スレッドが消失する問題対策。viewMode 切替後も selectedMessage
       が存在する場合は showReader を維持して reader を開いたままにする。 */
    const prevSelected = this.selectedMessage;
    this.updateViewMode();
    if (prevSelected) {
      // 選択中のメッセージがあれば reader を必ず開いた状態にする (SP/PC 双方共通)
      this.selectedMessage = prevSelected;
      this.showReader = true;
      this.cdr.markForCheck();
    }
  }

  @HostListener('window:keydown', ['$event'])
  onKeydown(event: KeyboardEvent): void {
    // Skip if user is typing in an input
    const target = event.target as HTMLElement;
    if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable) {
      return;
    }

    switch (event.key) {
      case 'c':
        event.preventDefault();
        this.onCompose();
        break;
      case 'r':
        if (this.selectedMessage) {
          event.preventDefault();
          this.onReply(this.selectedMessage);
        }
        break;
      case 'a':
        if (this.selectedMessage) {
          event.preventDefault();
          this.onReplyAll(this.selectedMessage);
        }
        break;
      case 'f':
        if (this.selectedMessage) {
          event.preventDefault();
          this.onForward(this.selectedMessage);
        }
        break;
      case 'j':
        event.preventDefault();
        this.navigateMessage(1);
        break;
      case 'k':
        event.preventDefault();
        this.navigateMessage(-1);
        break;
      case 'o':
      case 'Enter':
        if (this.selectedMessage) {
          event.preventDefault();
        }
        break;
      case 's':
        if (this.selectedMessage) {
          event.preventDefault();
          this.onStarToggle(this.selectedMessage.id);
        }
        break;
      case '#':
        if (this.selectedMessage) {
          event.preventDefault();
          this.onDeleteMessages([this.selectedMessage.id]);
        }
        break;
      case 'Escape':
        if (this.showCompose) {
          this.showCompose = false;
          this.cdr.markForCheck();
        } else if (this.showReader) {
          this.showReader = false;
          this.selectedMessage = null;
          this.cdr.markForCheck();
        }
        break;
    }
  }

  get folderName(): string {
    const folder = this.folders.find(f => f.id === this.selectedFolderId);
    return folder?.name || '受信トレイ';
  }

  get isMobileView(): boolean {
    return this.viewMode === 'single-pane' || this.viewMode === 'list-reader-toggle';
  }

  toggleMobileSidebar(): void {
    this.mobileSidebarOpen = !this.mobileSidebarOpen;
    this.cdr.markForCheck();
  }

  onMobileFolderSelected(folderId: string): void {
    this.mobileSidebarOpen = false;
    this.onFolderSelected(folderId);
  }

  get shouldShowSidebar(): boolean {
    return this.viewMode === 'three-pane' ||
      (this.viewMode === 'two-pane' && this.showSidebar) ||
      (this.viewMode !== 'single-pane' && this.viewMode !== 'list-reader-toggle');
  }

  get shouldShowList(): boolean {
    if (this.viewMode === 'single-pane' || this.viewMode === 'list-reader-toggle') {
      return !this.showReader;
    }
    // Desktop: respect layoutMode
    if (this.layoutMode === 'list') {
      return !this.showReader;
    }
    return true; // split mode: always show list
  }

  get shouldShowReader(): boolean {
    if (this.viewMode === 'single-pane' || this.viewMode === 'list-reader-toggle') {
      return this.showReader;
    }
    // Desktop: respect layoutMode
    if (this.layoutMode === 'list') {
      return this.showReader;
    }
    return true; // split mode: always show reader
  }

  // Data loading
  private loadFolders(): void {
    this.mailService.listFolders()
      .pipe(takeUntil(this.destroy$))
      .subscribe(folders => {
        this.folders = folders;
        this.cdr.markForCheck();
      });
  }

  private loadMessages(search?: string): void {
    const query: any = {};
    query.folderId = this.selectedFolderId;
    if (search) {
      query.search = search;
    }
    this.mailService.listMessages(query)
      .pipe(takeUntil(this.destroy$))
      .subscribe(messages => {
        this.messages = messages;
        this.cdr.markForCheck();
      });
  }

  private loadContacts(): void {
    this.mailService.getContacts()
      .pipe(takeUntil(this.destroy$))
      .subscribe(contacts => {
        this.contacts = contacts;
      });
  }

  private loadThread(threadId: string): void {
    this.mailService.getThreadMessages(threadId)
      .pipe(takeUntil(this.destroy$))
      .subscribe(messages => {
        this.threadMessages = messages;
        this.cdr.markForCheck();
      });
  }

  private updateViewMode(): void {
    const width = window.innerWidth;
    if (width >= 1280) {
      this.viewMode = 'three-pane';
    } else if (width >= 1024) {
      this.viewMode = 'two-pane';
      this.showSidebar = false;
    } else if (width >= 768) {
      this.viewMode = 'list-reader-toggle';
    } else {
      this.viewMode = 'single-pane';
    }
    this.cdr.markForCheck();
  }

  // Event handlers
  onFolderSelected(folderId: string): void {
    this.selectedFolderId = folderId;
    this.selectedMessage = null;
    this.threadMessages = [];
    this.showReader = false;
    this.loadMessages();
    this.loadFolders();
  }

  onMessageSelected(messageId: string): void {
    this.mailService.getMessage(messageId)
      .pipe(takeUntil(this.destroy$))
      .subscribe(message => {
        if (message) {
          this.selectedMessage = message;
          this.showReader = true;
          this.loadThread(message.threadId);

          if (!message.isRead) {
            this.mailService.markAsRead([messageId], true)
              .pipe(takeUntil(this.destroy$))
              .subscribe(() => {
                this.loadMessages();
                this.loadFolders();
              });
          }
          this.cdr.markForCheck();
        }
      });
  }

  onSearchChanged(term: string): void {
    this.loadMessages(term);
  }

  onStarToggle(messageId: string): void {
    this.mailService.toggleStar(messageId)
      .pipe(takeUntil(this.destroy$))
      .subscribe(updated => {
        if (this.selectedMessage?.id === messageId) {
          this.selectedMessage = updated;
        }
        this.loadMessages();
        this.loadFolders();
      });
  }

  onDeleteMessages(ids: string[]): void {
    this.mailService.deleteMessage(ids)
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => {
        if (this.selectedMessage && ids.includes(this.selectedMessage.id)) {
          this.selectedMessage = null;
          this.showReader = false;
        }
        this.loadMessages();
        this.loadFolders();

        this.notification.warn('メールを削除しました');
      });
  }

  onMoveMessages(event: { ids: string[]; folderId: string }): void {
    this.mailService.moveToFolder(event.ids, event.folderId)
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => {
        if (this.selectedMessage && event.ids.includes(this.selectedMessage.id)) {
          this.selectedMessage = null;
          this.showReader = false;
        }
        this.loadMessages();
        this.loadFolders();
      });
  }

  onReadToggle(ids: string[]): void {
    const firstMsg = this.messages.find(m => ids.includes(m.id));
    const newRead = firstMsg ? !firstMsg.isRead : true;
    this.mailService.markAsRead(ids, newRead)
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => {
        this.loadMessages();
        this.loadFolders();
      });
  }

  onMoveFromReader(event: { id: string; folderId: string }): void {
    this.onMoveMessages({ ids: [event.id], folderId: event.folderId });
  }

  onReadToggleFromReader(messageId: string): void {
    this.onReadToggle([messageId]);
    this.selectedMessage = null;
    this.showReader = false;
  }

  // Compose
  onCompose(): void {
    this.composeConfig = { mode: 'new' };
    this.showCompose = true;
    this.cdr.markForCheck();
  }

  onReply(message: MailMessage): void {
    this.composeConfig = { mode: 'reply', originalMessage: message };
    this.showCompose = true;
    this.cdr.markForCheck();
  }

  onReplyAll(message: MailMessage): void {
    this.composeConfig = { mode: 'replyAll', originalMessage: message };
    this.showCompose = true;
    this.cdr.markForCheck();
  }

  onForward(message: MailMessage): void {
    this.composeConfig = { mode: 'forward', originalMessage: message };
    this.showCompose = true;
    this.cdr.markForCheck();
  }

  onSendMail(draft: MailDraft): void {
    this.mailService.sendMessage(draft)
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => {
        this.showCompose = false;
        this.loadMessages();
        this.notification.success('メールを送信しました');
        this.cdr.markForCheck();
      });
  }

  onSaveDraft(_draft: MailDraft): void {
    // Mock save draft
    this.showCompose = false;
    this.notification.info('下書きを保存しました');
    this.cdr.markForCheck();
  }

  onComposeClose(): void {
    this.showCompose = false;
    this.cdr.markForCheck();
  }

  onQuickReply(event: { messageId: string; body: string }): void {
    const bodyHtml = `<div style="font-family: sans-serif;">${event.body.replace(/\n/g, '<br>')}</div>`;
    this.mailService.replyMessage(event.messageId, event.body, bodyHtml)
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => {
        if (this.selectedMessage) {
          this.loadThread(this.selectedMessage.threadId);
        }
        this.loadMessages();
        this.cdr.markForCheck();
      });
  }

  setLayoutMode(mode: 'split' | 'list'): void {
    this.layoutMode = mode;
    if (mode === 'list') {
      // In list mode, go back to list if reader was showing
      this.showReader = false;
      this.selectedMessage = null;
    }
    this.cdr.markForCheck();
  }

  onBackFromReader(): void {
    this.showReader = false;
    this.selectedMessage = null;
    this.cdr.markForCheck();
  }

  // Navigation
  private navigateMessage(direction: number): void {
    if (!this.messages.length) return;
    const currentIndex = this.selectedMessage
      ? this.messages.findIndex(m => m.id === this.selectedMessage!.id)
      : -1;
    const newIndex = Math.max(0, Math.min(this.messages.length - 1, currentIndex + direction));
    if (newIndex !== currentIndex) {
      this.onMessageSelected(this.messages[newIndex].id);
    }
  }
}
