import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatIconModule } from '@angular/material/icon';
import { MatIconButton } from '@angular/material/button';
import { MatTooltipModule } from '@angular/material/tooltip';
import { RelativeTimePipe } from '../../../../shared/pipes/relative-time.pipe';
import { TruncatePipe } from '../../../../shared/pipes/truncate.pipe';
import { MailMessage } from '../../models/mail.model';

/** アバター用カラーパレット */
const AVATAR_COLORS = [
  '#1a73e8', '#d93025', '#188038', '#e37400',
  '#a142f4', '#fa903e', '#1967d2', '#e52592',
];

/** 曜日名 */
const WEEKDAY_NAMES = ['日曜日', '月曜日', '火曜日', '水曜日', '木曜日', '金曜日', '土曜日'];

@Component({
  selector: 'app-mail-list-item',
  standalone: true,
  imports: [
    CommonModule,
    MatCheckboxModule,
    MatIconModule,
    MatIconButton,
    MatTooltipModule,
    RelativeTimePipe,
    TruncatePipe,
  ],
  templateUrl: './mail-list-item.component.html',
  styleUrls: ['./mail-list-item.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MailListItemComponent {
  @Input() message!: MailMessage;
  @Input() isSelected: boolean = false;
  @Input() isChecked: boolean = false;

  @Output() messageClick = new EventEmitter<string>();
  @Output() checkChanged = new EventEmitter<{ id: string; checked: boolean }>();
  @Output() starToggled = new EventEmitter<string>();
  @Output() deleteClicked = new EventEmitter<string>();
  @Output() readToggled = new EventEmitter<string>();
  @Output() archiveClicked = new EventEmitter<string>();

  showHoverActions = false;

  /** 送信者名の先頭1文字 */
  get senderInitial(): string {
    return (this.message.from.name || this.message.from.email || '?').charAt(0).toUpperCase();
  }

  /** 送信者名からハッシュしてアバター背景色を返す */
  get avatarColor(): string {
    const name = this.message.from.name || this.message.from.email || '';
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
      hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return AVATAR_COLORS[Math.abs(hash) % AVATAR_COLORS.length];
  }

  /** スマート日付フォーマット（Gmail風） */
  get smartDate(): string {
    const msgDate = new Date(this.message.date);
    const now = new Date();

    const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const yesterdayStart = new Date(todayStart.getTime() - 86400000);
    const weekAgoStart = new Date(todayStart.getTime() - 6 * 86400000);

    if (msgDate >= todayStart) {
      // 今日: 時刻のみ
      const h = msgDate.getHours().toString().padStart(2, '0');
      const m = msgDate.getMinutes().toString().padStart(2, '0');
      return `${h}:${m}`;
    } else if (msgDate >= yesterdayStart) {
      return '昨日';
    } else if (msgDate >= weekAgoStart) {
      return WEEKDAY_NAMES[msgDate.getDay()];
    } else if (msgDate.getFullYear() === now.getFullYear()) {
      return `${msgDate.getMonth() + 1}月${msgDate.getDate()}日`;
    } else {
      const y = msgDate.getFullYear();
      const mo = (msgDate.getMonth() + 1).toString().padStart(2, '0');
      const d = msgDate.getDate().toString().padStart(2, '0');
      return `${y}/${mo}/${d}`;
    }
  }

  onMessageClick(event: Event): void {
    event.stopPropagation();
    this.messageClick.emit(this.message.id);
  }

  onCheckChange(checked: boolean): void {
    this.checkChanged.emit({ id: this.message.id, checked });
  }

  onStarClick(event: Event): void {
    event.stopPropagation();
    this.starToggled.emit(this.message.id);
  }

  onDeleteClick(event: Event): void {
    event.stopPropagation();
    this.deleteClicked.emit(this.message.id);
  }

  onReadToggle(event: Event): void {
    event.stopPropagation();
    this.readToggled.emit(this.message.id);
  }

  onArchiveClick(event: Event): void {
    event.stopPropagation();
    this.archiveClicked.emit(this.message.id);
  }
}
