import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy, OnChanges, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { MatIconModule } from '@angular/material/icon';
import { MatButtonModule } from '@angular/material/button';
import { MatMenuModule } from '@angular/material/menu';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MatDividerModule } from '@angular/material/divider';
import { MatExpansionModule } from '@angular/material/expansion';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { RelativeTimePipe } from '../../../../shared/pipes/relative-time.pipe';
import { MailMessage, MailAddress } from '../../models/mail.model';

@Component({
  selector: 'app-mail-reader',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    MatIconModule,
    MatButtonModule,
    MatMenuModule,
    MatTooltipModule,
    MatDividerModule,
    MatExpansionModule,
    AvatarComponent,
    RelativeTimePipe,
  ],
  templateUrl: './mail-reader.component.html',
  styleUrls: ['./mail-reader.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MailReaderComponent implements OnChanges {
  @Input() message: MailMessage | null = null;
  @Input() threadMessages: MailMessage[] = [];
  @Input() showBackButton: boolean = false;
  @Output() replyClicked = new EventEmitter<MailMessage>();
  @Output() replyAllClicked = new EventEmitter<MailMessage>();
  @Output() forwardClicked = new EventEmitter<MailMessage>();
  @Output() deleteClicked = new EventEmitter<string>();
  @Output() starToggled = new EventEmitter<string>();
  @Output() moveRequested = new EventEmitter<{ id: string; folderId: string }>();
  @Output() readToggled = new EventEmitter<string>();
  @Output() quickReplySent = new EventEmitter<{ messageId: string; body: string }>();
  @Output() backClicked = new EventEmitter<void>();

  quickReplyText = '';
  showDetails = false;

  constructor(private sanitizer: DomSanitizer) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['message']) {
      this.quickReplyText = '';
      this.showDetails = false;
    }
  }

  get sanitizedBody(): SafeHtml {
    if (!this.message) return '';
    return this.sanitizer.bypassSecurityTrustHtml(this.message.bodyHtml);
  }

  getSanitizedBody(msg: MailMessage): SafeHtml {
    return this.sanitizer.bypassSecurityTrustHtml(msg.bodyHtml);
  }

  get isThread(): boolean {
    return this.threadMessages.length > 1;
  }

  get olderThreadMessages(): MailMessage[] {
    if (!this.message || this.threadMessages.length <= 1) return [];
    return this.threadMessages.filter(m => m.id !== this.message!.id);
  }

  formatRecipients(addresses: MailAddress[]): string {
    return addresses.map(a => a.name || a.email).join(', ');
  }

  formatDate(date: Date): string {
    const d = new Date(date);
    const year = d.getFullYear();
    const month = d.getMonth() + 1;
    const day = d.getDate();
    const hours = d.getHours().toString().padStart(2, '0');
    const minutes = d.getMinutes().toString().padStart(2, '0');
    return `${year}年${month}月${day}日 ${hours}:${minutes}`;
  }

  formatFileSize(bytes: number): string {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
  }

  getFileIcon(mimeType: string): string {
    if (mimeType.includes('pdf')) return 'picture_as_pdf';
    if (mimeType.includes('spreadsheet') || mimeType.includes('excel')) return 'table_chart';
    if (mimeType.includes('presentation') || mimeType.includes('powerpoint')) return 'slideshow';
    if (mimeType.includes('word') || mimeType.includes('document')) return 'description';
    if (mimeType.includes('image')) return 'image';
    return 'insert_drive_file';
  }

  onReply(): void {
    if (this.message) this.replyClicked.emit(this.message);
  }

  onReplyAll(): void {
    if (this.message) this.replyAllClicked.emit(this.message);
  }

  onForward(): void {
    if (this.message) this.forwardClicked.emit(this.message);
  }

  onDelete(): void {
    if (this.message) this.deleteClicked.emit(this.message.id);
  }

  onStarToggle(): void {
    if (this.message) this.starToggled.emit(this.message.id);
  }

  onMove(folderId: string): void {
    if (this.message) this.moveRequested.emit({ id: this.message.id, folderId });
  }

  onMarkUnread(): void {
    if (this.message) this.readToggled.emit(this.message.id);
  }

  onSendQuickReply(): void {
    if (this.message && this.quickReplyText.trim()) {
      this.quickReplySent.emit({
        messageId: this.message.id,
        body: this.quickReplyText.trim(),
      });
      this.quickReplyText = '';
    }
  }

  onBack(): void {
    this.backClicked.emit();
  }
}
